<?php
require dirname(__DIR__).'/app/bootstrap.php';Auth::requireAdmin();$adminTitle='Kontrol Leaderboard';$event=active_event();if(!$event){flash('warning','Belum ada event aktif.');redirect('admin/events.php');}
if(is_post()){try{verify_csrf();$action=(string)$_POST['action'];if($action==='settings'){$freeze=isset($_POST['leaderboard_frozen'])?1:0;if($freeze===1 && (int)$event['leaderboard_frozen']===0){LeaderboardService::createSnapshot((int)$event['id'],'BUJANG');LeaderboardService::createSnapshot((int)$event['id'],'DAYANG');}db()->prepare('UPDATE events SET leaderboard_visible=?,leaderboard_frozen=?,points_visible=?,updated_at=NOW() WHERE id=?')->execute([isset($_POST['leaderboard_visible'])?1:0,$freeze,isset($_POST['points_visible'])?1:0,$event['id']]);audit('UPDATE_LEADERBOARD_SETTINGS','events',(int)$event['id']);flash('success','Pengaturan leaderboard diperbarui.');}elseif($action==='adjust'){$finalistId=(int)$_POST['finalist_id'];$pts=(int)$_POST['points'];$reason=trim((string)$_POST['reason']);if($pts===0||$reason==='')throw new RuntimeException('Jumlah poin dan alasan wajib diisi.');$stmt=db()->prepare("INSERT INTO point_ledgers(event_id,finalist_id,vote_order_id,transaction_type,points,description,created_by,created_at) VALUES(?,?,NULL,'ADJUSTMENT',?,?,?,NOW())");$stmt->execute([$event['id'],$finalistId,$pts,$reason,Auth::id()]);audit('ADJUST_POINTS','finalists',$finalistId,null,['points'=>$pts,'reason'=>$reason]);flash('success','Penyesuaian poin dicatat pada ledger.');}redirect('admin/leaderboard.php');}catch(Throwable $e){flash('danger',$e->getMessage());redirect('admin/leaderboard.php');}}
$bujang=LeaderboardService::rankings((int)$event['id'],'BUJANG',null,false);$dayang=LeaderboardService::rankings((int)$event['id'],'DAYANG',null,false);$finalists=array_merge($bujang,$dayang);$ledger=db()->prepare("SELECT pl.*,f.full_name,u.name admin_name FROM point_ledgers pl JOIN finalists f ON f.id=pl.finalist_id LEFT JOIN users u ON u.id=pl.created_by WHERE pl.event_id=? AND pl.transaction_type='ADJUSTMENT' ORDER BY pl.id DESC LIMIT 20");$ledger->execute([$event['id']]);$adjustments=$ledger->fetchAll();require __DIR__.'/partials/header.php';
?>
<div class="row g-4 mb-4"><div class="col-xl-5"><div class="admin-card p-4"><h5>Pengaturan Tampilan</h5><form method="post" class="mt-4"><?= csrf_field() ?><input type="hidden" name="action" value="settings"><div class="form-check form-switch mb-3"><input class="form-check-input" type="checkbox" name="leaderboard_visible" <?= $event['leaderboard_visible']?'checked':'' ?>><label class="form-check-label">Tampilkan leaderboard publik</label></div><div class="form-check form-switch mb-3"><input class="form-check-input" type="checkbox" name="leaderboard_frozen" <?= $event['leaderboard_frozen']?'checked':'' ?>><label class="form-check-label">Bekukan pembaruan tampilan publik</label></div><div class="form-check form-switch mb-4"><input class="form-check-input" type="checkbox" name="points_visible" <?= $event['points_visible']?'checked':'' ?>><label class="form-check-label">Tampilkan angka poin</label></div><button class="btn btn-admin">Simpan Pengaturan</button></form></div></div><div class="col-xl-7"><div class="admin-card p-4"><h5>Penyesuaian Poin</h5><div class="alert alert-warning small">Gunakan hanya untuk koreksi yang memiliki bukti. Nilai negatif akan mengurangi poin. Transaksi asli tidak diubah.</div><form method="post" class="row g-3"><?= csrf_field() ?><input type="hidden" name="action" value="adjust"><div class="col-md-6"><label class="form-label">Finalis</label><select class="form-select" name="finalist_id" required><?php foreach($finalists as $f):?><option value="<?= (int)$f['id'] ?>"><?= e($f['category'].' '.$f['contestant_number'].' - '.$f['full_name']) ?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Jumlah Poin (+/-)</label><input class="form-control" type="number" name="points" required></div><div class="col-12"><label class="form-label">Alasan dan Referensi Bukti</label><textarea class="form-control" name="reason" rows="2" required></textarea></div><div class="col-12"><button class="btn btn-gold-admin">Catat Penyesuaian</button></div></form></div></div></div>
<?php foreach([['Bujang',$bujang],['Dayang',$dayang]] as [$label,$rows]):?><div class="admin-card overflow-hidden mb-4"><div class="p-4"><h5 class="mb-0">Peringkat <?= $label ?></h5></div><div class="table-responsive"><table class="table table-admin"><thead><tr><th>Rank</th><th>Finalis</th><th>Asal</th><th>Total Poin</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><span class="badge text-bg-success"><?= (int)$r['rank'] ?></span></td><td><strong><?= e($r['contestant_number'].' - '.$r['full_name']) ?></strong></td><td><?= e($r['region_name']) ?></td><td class="fw-bold text-success"><?= number_format((int)$r['total_points'],0,',','.') ?></td></tr><?php endforeach;?></tbody></table></div></div><?php endforeach;?>
<div class="admin-card overflow-hidden"><div class="p-4"><h5 class="mb-0">Riwayat Penyesuaian</h5></div><div class="table-responsive"><table class="table table-admin"><thead><tr><th>Tanggal</th><th>Finalis</th><th>Poin</th><th>Alasan</th><th>Admin</th></tr></thead><tbody><?php foreach($adjustments as $a):?><tr><td><?= indonesia_date($a['created_at'],true) ?></td><td><?= e($a['full_name']) ?></td><td class="fw-bold <?= $a['points']>=0?'text-success':'text-danger' ?>"><?= $a['points']>=0?'+':'' ?><?= number_format((int)$a['points'],0,',','.') ?></td><td><?= e($a['description']) ?></td><td><?= e($a['admin_name']??'-') ?></td></tr><?php endforeach;?></tbody></table></div></div>
<?php require __DIR__.'/partials/footer.php';?>
